import * as THREE from 'three/webgpu';
import { texture, uv, vec4, color, mix, uniform, float } from 'three/tsl';
import { gsap } from 'gsap';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-pricing-quote-panel';
  group.position.set(1.25, 1.6, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 2.2;
  const height = 1.375;
  const geometry = new THREE.PlaneGeometry(width, height);

  const tex = ctx.textureLoader.load('/prism-mock/home/nodes/feature-card.png');
  tex.colorSpace = THREE.SRGBColorSpace;

  const hoverAmount = uniform(0);
  const accentColor = color(0xff2a38);
  const inkColor = color(0x16161d);

  const material = new THREE.MeshBasicNodeMaterial();
  const baseTex = texture(tex, uv());
  const edgeMix = uv().x.smoothstep(0.0, 0.02).oneMinus().add(uv().x.smoothstep(0.98, 1.0));
  const tinted = mix(baseTex, mix(baseTex, accentColor, float(0.15)), hoverAmount);
  material.colorNode = vec4(tinted.rgb.add(edgeMix.mul(hoverAmount).mul(0.05)), baseTex.a);
  material.transparent = true;

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Quote text
  const quoteText = createTextMesh({
    text: '"The precision of a machine, the soul of a craftsman."',
    font: 'Lora',
    weight: 400,
    size: 0.13,
    color: '#e8ecf2',
    maxWidth: width - 0.5,
    align: 'left',
    fontAtlas: ctx.fontAtlas,
  });
  quoteText.position.set(-width / 2 + 0.25, height / 2 - 0.4, 0.01);
  group.add(quoteText);

  const attributionText = createTextMesh({
    text: '— A. Reyes, Collector',
    font: 'JetBrains Mono',
    weight: 700,
    size: 0.09,
    color: '#ff2a38',
    maxWidth: width - 0.5,
    align: 'left',
    fontAtlas: ctx.fontAtlas,
  });
  attributionText.position.set(-width / 2 + 0.25, -height / 2 + 0.25, 0.01);
  group.add(attributionText);

  // Apply cinematic primitives
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((primitive) => {
      const fn = ctx.primitives[primitive.name];
      if (typeof fn === 'function') {
        fn(group, primitive.params);
      }
    });
  }

  // Interaction state
  let hoverTl = null;
  let pressTl = null;
  const basePosY = group.position.y;

  const onPointerOver = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, { y: basePosY + 0.15, duration: 0.7, ease: 'power3.out' }, 0);
    hoverTl.to(hoverAmount, { value: 1, duration: 0.7, ease: 'power3.out' }, 0);
  };

  const onPointerOut = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, { y: basePosY, duration: 0.7, ease: 'power3.out' }, 0);
    hoverTl.to(hoverAmount, { value: 0, duration: 0.7, ease: 'power3.out' }, 0);
  };

  const onClick = () => {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline();
    pressTl.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' })
      .to(group.scale, { x: 1, y: 1, z: 1, duration: 0.12, ease: 'back.out' });

    if (group.userData.emit) {
      group.userData.emit('hub-pricing.select', { nodeId: group.name });
    }
  };

  group.userData.handlers = {
    onPointerOver,
    onPointerOut,
    onClick,
  };

  group.userData.cleanup = () => {
    if (hoverTl) hoverTl.kill();
    if (pressTl) pressTl.kill();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(hoverAmount);
    geometry.dispose();
    material.dispose();
    tex.dispose();
    if (quoteText.geometry) quoteText.geometry.dispose();
    if (quoteText.material) quoteText.material.dispose();
    if (attributionText.geometry) attributionText.geometry.dispose();
    if (attributionText.material) attributionText.material.dispose();
  };

  return group;
}
